INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_APOSTOLIC','Apostolic Age',1,100)
INSERT INTO _e VALUES
 ('ENT_ISR_PATRIARCHS','The Patriarchs (Avot)','Israelite/Second Temple','Collective','Biblical collective','the three forefathers; covenant lineage','A','The three forefathers of Israel — Abraham, Isaac, and Jacob — invoked together as the recipients of the covenant.'),
 ('ENT_ISR_MATRIARCHS','The Matriarchs (Imahot)','Israelite/Second Temple','Collective','Biblical collective','the four foremothers; covenant lineage','A','The four foremothers of Israel — Sarah, Rebecca, Rachel, and Leah — mothers of the covenant line.'),
 ('ENT_ISR_TWELVE_TRIBES','The Twelve Tribes of Israel','Israelite/Second Temple','Collective','Biblical collective','the sons of Jacob; the tribal confederation','A','The confederation of tribes descended from the sons of Jacob, who together constituted the people of Israel.'),
 ('ENT_ISR_JUDGES','The Judges of Israel','Israelite/Second Temple','Collective','Biblical collective','charismatic deliverers; pre-monarchic leadership','A','The charismatic deliverers who led the tribes of Israel in the period before the monarchy.'),
 ('ENT_ISR_KINGS','The Kings of the United Monarchy','Israelite/Second Temple','Collective','Biblical collective','the united monarchy; Saul, David, Solomon','A','The three successive kings of the united Israelite kingdom — Saul, David, and Solomon — before its division.'),
 ('ENT_ISR_EVE','Eve','Israelite/Second Temple','Biblical figure','Primeval matriarch','first woman; mother of humanity; the Fall','A','Formed as the first woman and ''mother of all living,'' she eats the forbidden fruit and bears Cain, Abel, and Seth.'),
 ('ENT_ISR_CAIN','Cain','Israelite/Second Temple','Biblical figure','Primeval figure','firstborn of humanity; agriculture; fratricide','A','Firstborn son of Adam and Eve, a tiller of the ground who murdered his brother Abel and was marked and exiled.'),
 ('ENT_ISR_ABEL','Abel','Israelite/Second Temple','Biblical figure','Primeval figure','shepherding; accepted sacrifice; the first death','A','Second son of Adam and Eve, a keeper of sheep whose offering was favored and who was slain by his brother Cain.'),
 ('ENT_ISR_SETH','Seth','Israelite/Second Temple','Patriarch','Antediluvian patriarch','third son of Adam; the righteous line to Noah','A','Third son of Adam and Eve, given in place of slain Abel, through whose line Enosh, Enoch, and Noah descend.'),
 ('ENT_ISR_ABRAHAM','Abraham','Israelite/Second Temple','Patriarch','Biblical patriarch','covenant; faith; the binding of Isaac; father of nations','A','First of the patriarchs, called from Ur, recipient of the covenant, father of Ishmael by Hagar and Isaac by Sarah.'),
 ('ENT_ISR_SARAH','Sarah','Israelite/Second Temple','Matriarch','Biblical matriarch','matriarch; the promised son; the covenant line','A','Wife of Abraham and first matriarch, who bore Isaac in old age after the promise of a son.'),
 ('ENT_ISR_HAGAR','Hagar','Israelite/Second Temple','Biblical figure','Mother of Ishmael','the wilderness; divine encounter; mother of Ishmael','A','Egyptian servant of Sarah who bore Abraham''s son Ishmael and was met by the angel of Yahweh in the wilderness.'),
 ('ENT_ISR_ISHMAEL','Ishmael','Israelite/Second Temple','Patriarch','Ancestor of the Ishmaelites','firstborn of Abraham; wilderness; ancestor of twelve princes','A','Firstborn son of Abraham by Hagar, ancestor of twelve princes, who dwelt in the wilderness of Paran.'),
 ('ENT_ISR_LOT','Lot','Israelite/Second Temple','Biblical figure','Nephew of Abraham','Sodom and Gomorrah; rescue from destruction','A','Nephew of Abraham (son of Haran) who settled in Sodom and was delivered from its destruction (Genesis 13, 19).'),
 ('ENT_ISR_ISAAC','Isaac','Israelite/Second Temple','Patriarch','Biblical patriarch','the promised son; the Akedah; covenant continuity','A','Son of Abraham and Sarah, bound on Mount Moriah, husband of Rebecca, and father of Esau and Jacob.'),
 ('ENT_ISR_REBECCA','Rebecca','Israelite/Second Temple','Matriarch','Biblical matriarch','matriarch; the well; mother of Jacob and Esau','A','Wife of Isaac, found at the well, mother of twins Esau and Jacob whom she helped secure the blessing.'),
 ('ENT_ISR_JACOB','Jacob (Israel)','Israelite/Second Temple','Patriarch','Eponym of Israel','the ladder vision; wrestling the angel; father of the twelve tribes','A','Son of Isaac and Rebecca, renamed Israel after wrestling at Peniel, father of the twelve sons who became the tribes of Israel.'),
 ('ENT_ISR_RACHEL','Rachel','Israelite/Second Temple','Matriarch','Biblical matriarch','the beloved wife; mother of Joseph and Benjamin','A','Beloved wife of Jacob, mother of Joseph and Benjamin, who died in childbirth near Bethlehem.'),
 ('ENT_ISR_LEAH','Leah','Israelite/Second Temple','Matriarch','Biblical matriarch','matriarch; mother of six tribes incl. Levi and Judah','A','First wife of Jacob and mother of six of his sons, including Levi and Judah, ancestors of priesthood and kingship.'),
 ('ENT_ISR_JOSEPH','Joseph (son of Jacob)','Israelite/Second Temple','Patriarch','Patriarch / vizier of Egypt','dreams; bondage and exaltation; provision in famine','A','Favored son of Jacob and Rachel, sold into Egypt, who rose to vizier and preserved his family during famine.'),
 ('ENT_ISR_JUDAH','Judah','Israelite/Second Temple','Patriarch','Eponym of the tribe of Judah','tribal ancestor; the royal line; the scepter blessing','A','Fourth son of Jacob and Leah and ancestor of the royal Davidic line, blessed that the scepter would not depart.'),
 ('ENT_ISR_LEVI','Levi','Israelite/Second Temple','Patriarch','Eponym of the priestly tribe','tribal ancestor; the priestly line','A','Third son of Jacob and Leah and ancestor of the priestly tribe of Levi, including Moses and Aaron.'),
 ('ENT_ISR_BENJAMIN','Benjamin','Israelite/Second Temple','Patriarch','Eponym of the tribe of Benjamin','youngest son of Jacob; tribal ancestor','A','Youngest son of Jacob and Rachel, born at her death, ancestor of the tribe of Benjamin and of King Saul.'),
 ('ENT_ISR_AARON','Aaron','Israelite/Second Temple','Priest','First high priest of Israel','the priesthood; spokesman of Moses; the golden calf','A','Brother of Moses and Miriam, spokesman before Pharaoh, and the first high priest of Israel.'),
 ('ENT_ISR_MIRIAM','Miriam','Israelite/Second Temple','Prophet','Prophetess / sister of Moses','prophecy; the song at the sea; leadership of the women','A','Sister of Moses and Aaron, called a prophetess, who led the women in song after the crossing of the sea.'),
 ('ENT_ISR_JOSHUA','Joshua','Israelite/Second Temple','Hero','Conquest leader / successor of Moses','conquest of Canaan; warfare; covenant renewal','A','Successor of Moses who led Israel across the Jordan and in the conquest of Canaan, dividing the land among the tribes.'),
 ('ENT_ISR_CALEB','Caleb','Israelite/Second Temple','Hero','Faithful spy / conquest figure','faithful scouting; inheritance of Hebron; wholehearted devotion','A','One of the twelve spies who, with Joshua, trusted in Yahweh and was rewarded with the inheritance of Hebron.'),
 ('ENT_ISR_DEBORAH','Deborah','Israelite/Second Temple','Judge','Prophetess and judge','prophecy; judgeship; the victory over Sisera','A','Prophetess and judge who summoned Barak and celebrated the defeat of Sisera in the Song of Deborah.'),
 ('ENT_ISR_GIDEON','Gideon','Israelite/Second Temple','Judge','Judge / military deliverer','deliverance from Midian; the fleece sign; the three hundred','A','Judge who, with three hundred men, delivered Israel from the Midianites after testing Yahweh with the fleece.'),
 ('ENT_ISR_SAMSON','Samson','Israelite/Second Temple','Judge','Judge / Nazirite strongman','superhuman strength; the Nazirite vow; war with the Philistines','A','Nazirite judge of immense strength who fought the Philistines and died bringing down their temple at Gaza.'),
 ('ENT_ISR_SAMUEL','Samuel','Israelite/Second Temple','Prophet','Prophet and last judge','prophecy; judgeship; anointing of Saul and David','A','Last judge and a prophet who anointed both Saul and David as kings of Israel.'),
 ('ENT_ISR_SAUL','Saul','Israelite/Second Temple','King','First king of Israel','the first monarchy; rejected kingship; war with the Philistines','A','First king of Israel from the tribe of Benjamin, anointed by Samuel, rejected for disobedience, and slain at Gilboa.'),
 ('ENT_ISR_DAVID','David','Israelite/Second Temple','King','King of the United Monarchy','kingship; the Davidic covenant; psalmody; warfare','A','Shepherd anointed by Samuel who slew Goliath, became king over all Israel, and received the everlasting dynastic covenant.'),
 ('ENT_ISR_BATHSHEBA','Bathsheba','Israelite/Second Temple','Queen','Queen / mother of Solomon','the royal household; mother of Solomon','A','Wife of David, taken after the death of Uriah, and mother of King Solomon.'),
 ('ENT_ISR_RUTH','Ruth','Israelite/Second Temple','Heroine','Moabite ancestress of David','loyalty (hesed); the gleaning; redemption; ancestress of David','A','Moabite widow whose loyalty to Naomi led to her marriage to Boaz, making her great-grandmother of King David.'),
 ('ENT_ISR_ESTHER','Esther','Israelite/Second Temple','Queen','Queen of Persia / deliverer of the Jews','deliverance of her people; the feast of Purim; courage','A','Jewish queen of Persia who risked her life before Ahasuerus to save her people, commemorated at Purim.'),
 ('ENT_ISR_MORDECAI','Mordecai','Israelite/Second Temple','Biblical figure','Jewish courtier / guardian of Esther','the foiling of Haman; the institution of Purim','A','Kinsman and guardian of Esther who uncovered a plot, refused homage to Haman, and helped establish Purim.'),
 ('ENT_ISR_JOB','Job','Israelite/Second Temple','Biblical figure','Righteous sufferer','undeserved suffering; perseverance; the divine speeches','A','A blameless man of Uz whose endurance of catastrophic suffering frames the book''s debate on divine justice.'),
 ('ENT_ISR_EZRA','Ezra','Israelite/Second Temple','Priest','Priest-scribe of the restoration','the Torah; restoration of the law; communal reform','A','Priest and scribe who led returning exiles and re-established the Torah in restored Jerusalem.'),
 ('ENT_ISR_NEHEMIAH','Nehemiah','Israelite/Second Temple','Biblical figure','Governor of the restoration','rebuilding Jerusalem''s walls; civic reform; covenant renewal','A','Cupbearer to the Persian king who became governor and rebuilt the walls of Jerusalem and reformed the community.'),
 ('ENT_ISR_LATTER_PROPHETS','The Latter Prophets (Nevi''im Aharonim)','Israelite/Second Temple','Collective','Prophetic collective','prophecy; covenant judgment and restoration; messianic hope','A','The prophetic canon division comprising the three Major Prophets and the Book of the Twelve, spanning the Assyrian, Babylonian, and Persian periods.'),
 ('ENT_ISR_TWELVE_PROPHETS','The Twelve Minor Prophets (Trei Asar)','Israelite/Second Temple','Collective','Prophetic collective','prophecy; social justice; the Day of the Lord; restoration','A','A single scroll in the Hebrew canon gathering twelve shorter prophetic books from the 8th century BCE to the post-exilic restoration.'),
 ('ENT_ISR_ISAIAH','Isaiah','Israelite/Second Temple','Prophet','Major prophet','judgment; messianic hope; the suffering servant; the holiness of God','A','An 8th-century BCE Judahite prophet whose oracles warn of judgment yet promise a remnant, a Davidic messiah, and a restored Zion.'),
 ('ENT_ISR_JEREMIAH','Jeremiah','Israelite/Second Temple','Prophet','Major prophet','judgment; lament; the new covenant; faithfulness in exile','A','A late 7th- to early 6th-century BCE prophet who foretold Jerusalem''s fall to Babylon and proclaimed a coming new covenant written on the heart.'),
 ('ENT_ISR_EZEKIEL','Ezekiel','Israelite/Second Temple','Prophet','Major prophet','exilic visions; divine glory; judgment and restoration','A','A 6th-century BCE priest-prophet among the Babylonian exiles whose visions of the chariot, dry bones, and a restored temple promise renewal.'),
 ('ENT_ISR_DANIEL_PROPHET','Daniel','Israelite/Second Temple','Prophet','Major prophet','apocalyptic vision; divine sovereignty over empires; eschatology','A','A Judahite exile at the Babylonian and Persian courts whose faithfulness and apocalyptic visions affirm God''s rule over the kingdoms of the world.'),
 ('ENT_ISR_HOSEA','Hosea','Israelite/Second Temple','Prophet','Minor prophet','covenant love; Israel''s unfaithfulness; divine mercy','A','An 8th-century BCE prophet to the northern kingdom whose troubled marriage dramatizes Israel''s faithlessness and God''s enduring covenant love.'),
 ('ENT_ISR_JOEL','Joel','Israelite/Second Temple','Prophet','Minor prophet','the Day of the Lord; locust plague; outpouring of the Spirit','A','A prophet of Judah who reads a devastating locust plague as a sign of the coming Day of the Lord and promises an outpouring of God''s Spirit.'),
 ('ENT_ISR_AMOS','Amos','Israelite/Second Temple','Prophet','Minor prophet','social justice; judgment on the nations; righteousness over ritual','A','A mid-8th-century BCE Judahite shepherd who prophesied against the northern kingdom, condemning injustice and empty worship.'),
 ('ENT_ISR_OBADIAH','Obadiah','Israelite/Second Temple','Prophet','Minor prophet','judgment on Edom; vindication of Zion; the Day of the Lord','A','Author of the shortest book of the Hebrew Bible, an oracle of judgment against Edom for its betrayal of Judah.'),
 ('ENT_ISR_JONAH','Jonah','Israelite/Second Temple','Prophet','Minor prophet','divine mercy to the nations; reluctant prophecy; repentance','A','A reluctant prophet, swallowed by a great fish, whose mission to Nineveh reveals God''s compassion even toward Israel''s enemies.'),
 ('ENT_ISR_MICAH','Micah','Israelite/Second Temple','Prophet','Minor prophet','social justice; judgment on Samaria and Jerusalem; the Bethlehem ruler','A','An 8th-century BCE contemporary of Isaiah who called Israel to do justice, love mercy, and walk humbly with God.'),
 ('ENT_ISR_NAHUM','Nahum','Israelite/Second Temple','Prophet','Minor prophet','judgment on Nineveh; divine vengeance; comfort for Judah','A','A 7th-century BCE prophet who proclaimed the impending fall of Nineveh as God''s judgment on a cruel empire.'),
 ('ENT_ISR_HABAKKUK','Habakkuk','Israelite/Second Temple','Prophet','Minor prophet','theodicy; faith amid injustice; ''the righteous shall live by faith''','A','A late 7th-century BCE prophet who questioned God about the Babylonian threat and concluded that the righteous shall live by their faith.'),
 ('ENT_ISR_ZEPHANIAH','Zephaniah','Israelite/Second Temple','Prophet','Minor prophet','the Day of the Lord; universal judgment; the humble remnant','A','A 7th-century BCE Judahite prophet during Josiah''s reign who warned of a sweeping Day of the Lord and promised salvation for a humble remnant.'),
 ('ENT_ISR_HAGGAI','Haggai','Israelite/Second Temple','Prophet','Minor prophet','rebuilding the temple; post-exilic restoration; priorities of worship','A','A post-exilic prophet of 520 BCE who urged the returned exiles to rebuild the Jerusalem temple and promised future glory.'),
 ('ENT_ISR_ZECHARIAH','Zechariah','Israelite/Second Temple','Prophet','Minor prophet','apocalyptic visions; temple restoration; messianic hope','A','A post-exilic prophet, contemporary of Haggai, whose night visions encouraged the temple''s rebuilding and foretold a coming messianic king.'),
 ('ENT_ISR_MALACHI','Malachi','Israelite/Second Temple','Prophet','Minor prophet','covenant fidelity; corrupt priesthood; the coming messenger','A','The last of the Twelve, a 5th-century BCE prophet who rebuked unfaithfulness and announced a coming messenger before the Day of the Lord.'),
 ('ENT_ISR_ELISHA','Elisha','Israelite/Second Temple','Prophet','Narrative prophet','prophetic succession; miracles; care for the lowly','A','A 9th-century BCE prophet of the northern kingdom who succeeded Elijah, receiving a double portion of his spirit and performing many miracles.'),
 ('ENT_ISR_NATHAN','Nathan','Israelite/Second Temple','Prophet','Narrative prophet','court prophecy; the Davidic covenant; royal accountability','A','A 10th-century BCE court prophet under King David who delivered the Davidic covenant promise and rebuked David over Bathsheba and Uriah.'),
 ('ENT_NT_TWELVE_APOSTLES','The Twelve Apostles','Christian/Biblical','Collective','Apostolic collective','the twelve disciples chosen by Jesus; foundation of the Church','A','The twelve disciples chosen by Jesus as his closest followers and witnesses, the foundation of the apostolic Church.'),
 ('ENT_NT_FOUR_EVANGELISTS','The Four Evangelists','Christian/Biblical','Collective','Apostolic collective','the authors of the four canonical Gospels','A','Matthew, Mark, Luke, and John — the traditional authors of the four canonical Gospels.'),
 ('ENT_NT_PAULINE_CIRCLE','The Pauline Circle','Christian/Biblical','Collective','Apostolic collective','companions and coworkers of the apostle Paul','A','The missionary companions and coworkers of the apostle Paul named in Acts and the epistles — Barnabas, Mark, Luke, Timothy, and Titus.'),
 ('ENT_NT_ANDREW','Andrew','Christian/Biblical','Apostle','Apostle','first-called apostle; brother of Peter; the saltire cross','A','A fisherman of Bethsaida and brother of Simon Peter, called by Jesus to be a fisher of men and numbered among the Twelve.'),
 ('ENT_NT_JOHN_APOSTLE','John, son of Zebedee','Christian/Biblical','Apostle and Evangelist','Apostle and Evangelist','the beloved disciple; the Fourth Gospel; Revelation','A','Son of Zebedee and brother of James the Greater, traditionally identified with the Beloved Disciple and reckoned both apostle and evangelist.'),
 ('ENT_NT_PHILIP','Philip','Christian/Biblical','Apostle','Apostle','apostle of Bethsaida; bringer of Nathanael; questioner at the Supper','A','A native of Bethsaida who, on being called by Jesus, sought out Nathanael with the words ''Come and see.'''),
 ('ENT_NT_BARTHOLOMEW','Bartholomew (Nathanael)','Christian/Biblical','Apostle','Apostle','apostle; ''an Israelite without guile''; identified with Nathanael','A','Listed among the Twelve as Bartholomew and commonly identified with the Nathanael whom Jesus praised as guileless in John''s Gospel.'),
 ('ENT_NT_THOMAS','Thomas','Christian/Biblical','Apostle','Apostle','doubt and confession; called Didymus; ''My Lord and my God''','A','An apostle called Didymus who doubted the resurrection until he saw the risen Christ, then confessed him as ''My Lord and my God.'''),
 ('ENT_NT_MATTHEW','Matthew (Levi)','Christian/Biblical','Apostle and Evangelist','Apostle and Evangelist','tax collector called by Jesus; the First Gospel','A','A tax collector (the Levi of Mark and Luke) called by Jesus, numbered among the Twelve and traditionally credited with the First Gospel.'),
 ('ENT_NT_JAMES_ALPHAEUS','James, son of Alphaeus','Christian/Biblical','Apostle','Apostle','apostle of the Twelve; ''James the Less''','A','An apostle named in all four lists of the Twelve as the son of Alphaeus, distinct from James the son of Zebedee.'),
 ('ENT_NT_JUDE_THADDAEUS','Jude (Thaddaeus)','Christian/Biblical','Apostle','Apostle','apostle; Thaddaeus / ''Judas of James''','A','An apostle listed as Thaddaeus in Matthew and Mark and as Judas son (or brother) of James in Luke and Acts.'),
 ('ENT_NT_SIMON_ZEALOT','Simon the Zealot','Christian/Biblical','Apostle','Apostle','apostle; the Zealot / the Cananaean','A','An apostle of the Twelve called the Zealot (or Cananaean) to distinguish him from Simon Peter.'),
 ('ENT_NT_JUDAS_ISCARIOT','Judas Iscariot','Christian/Biblical','Apostle','Apostle','betrayal; keeper of the money bag; thirty pieces of silver','A','The apostle who betrayed Jesus for thirty pieces of silver and afterward died, his place among the Twelve filled by Matthias.'),
 ('ENT_NT_MATTHIAS','Matthias','Christian/Biblical','Apostle','Apostle','apostle chosen by lot to replace Judas Iscariot','A','A disciple who had followed Jesus from his baptism and was chosen by lot to take the place of Judas Iscariot among the Twelve.'),
 ('ENT_NT_MARK','Mark','Christian/Biblical','Evangelist','Evangelist','evangelist; the Second Gospel; companion of Paul, Barnabas, Peter','A','John Mark, a companion of Paul, Barnabas, and Peter, traditionally identified as the author of the Second Gospel.'),
 ('ENT_NT_LUKE','Luke','Christian/Biblical','Evangelist','Evangelist','evangelist and physician; the Third Gospel and Acts; companion of Paul','A','A physician and companion of Paul, traditionally credited with the Third Gospel and the Acts of the Apostles.'),
 ('ENT_NT_BARNABAS','Barnabas','Christian/Biblical','Apostle','Apostolic missionary','''son of encouragement''; missionary companion of Paul','A','A Levite of Cyprus surnamed Barnabas (''son of encouragement'') who introduced Paul to the apostles and traveled with him as a missionary.'),
 ('ENT_NT_TIMOTHY','Timothy','Christian/Biblical','Disciple','Apostolic coworker','Paul''s coworker and delegate; leader at Ephesus','A','A disciple of Lystra, son of a Jewish mother and Greek father, who became Paul''s close coworker and the recipient of two epistles.'),
 ('ENT_NT_TITUS','Titus','Christian/Biblical','Disciple','Apostolic coworker','Paul''s Greek coworker; envoy to Corinth; organizer in Crete','A','A Greek coworker of Paul, sent to Corinth and left in Crete to set its churches in order, and the recipient of the Epistle to Titus.'),
 ('ENT_NT_LAZARUS_BETHANY','Lazarus of Bethany','Christian/Biblical','Biblical figure','Gospel figure','raised from the dead by Jesus; brother of Martha and Mary','A','The brother of Martha and Mary of Bethany, whom Jesus raised from the dead after four days in the tomb.'),
 ('ENT_NT_MARTHA','Martha','Christian/Biblical','Disciple','Gospel figure','hostess of Jesus at Bethany; confessor of Christ','A','A sister of Lazarus and Mary who served Jesus at Bethany and confessed him as the Christ, the Son of God.'),
 ('ENT_NT_NICODEMUS','Nicodemus','Christian/Biblical','Disciple','Gospel figure','Pharisee who came to Jesus by night; helped bury Jesus','A','A Pharisee and member of the Sanhedrin who came to Jesus by night and later helped Joseph of Arimathea bury him.'),
 ('ENT_ISL_PROPHETS','The Prophets of Islam (Anbiya)','Islamic','Collective','Islamic prophetic collective','the line of prophets and messengers; revelation; pure monotheism (tawhid)','A','The collective of prophets named in the Qur''an, from Adam to Muhammad, sent to guide humanity to the worship of the one God.'),
 ('ENT_ISL_ULU_AL_AZM','Ulu al-Azm','Islamic','Collective','Islamic prophetic collective','the five arch-prophets of firm resolve, each bringing a major scripture/law','A','Ulu al-Azm (''those of firm resolve'') are the five greatest messengers in Islam: Nuh, Ibrahim, Musa, Isa, and Muhammad.'),
 ('ENT_ISL_ADAM','Adam (Islam)','Islamic','Prophet','Islamic prophet','the first human and first prophet; God''s vicegerent (khalifa); the names of all things','A','Adam, the first man and first prophet in Islam, created by God and taught the names of all things; the Islamic reception of the Biblical Adam.'),
 ('ENT_ISL_NUH','Nuh','Islamic','Messenger (rasul)','Islamic prophet','the Ark and the Flood; persistent call to monotheism; Ulu al-Azm','A','Nuh built the Ark at God''s command and was saved with the believers from the Flood; the Islamic reception of Noah.'),
 ('ENT_ISL_HUD','Hud','Islamic','Messenger (rasul)','Islamic prophet','prophet to the people of ''Ad; warning against idolatry and arrogance','A','Hud was sent to the ancient Arabian people of ''Ad to call them from idolatry; an Arabian prophet with no Biblical counterpart.'),
 ('ENT_ISL_SALIH','Salih','Islamic','Messenger (rasul)','Islamic prophet','prophet to Thamud; the miraculous she-camel','A','Salih was sent to the Arabian people of Thamud with the sign of the she-camel; an Arabian prophet with no Biblical counterpart.'),
 ('ENT_ISL_IBRAHIM','Ibrahim','Islamic','Messenger (rasul)','Islamic prophet','khalil Allah (friend of God); the Kaaba; pure monotheism (hanif); Ulu al-Azm','A','Ibrahim, the friend of God, patriarch of monotheism who with his son built the Kaaba; the Islamic reception of Abraham.'),
 ('ENT_ISL_LUT','Lut','Islamic','Messenger (rasul)','Islamic prophet','prophet to the cities of the plain; warning against immorality','A','Lut warned his people against immorality before their destruction; the Islamic reception of Lot.'),
 ('ENT_ISL_ISMAIL','Ismail','Islamic','Prophet','Islamic prophet','son of Ibrahim; the son of the sacrifice; co-builder of the Kaaba; ancestor of the Arabs','A','Ismail, son of Ibrahim, helped build the Kaaba and is regarded in Islam as the son offered in sacrifice; the Islamic reception of Ishmael.'),
 ('ENT_ISL_ISHAQ','Ishaq','Islamic','Prophet','Islamic prophet','son of Ibrahim; patriarch of the Israelite prophets','A','Ishaq, son of Ibrahim, was given to him in old age and continued the prophetic line; the Islamic reception of Isaac.'),
 ('ENT_ISL_YAQUB','Yaqub','Islamic','Prophet','Islamic prophet','son of Ishaq; also called Israil; patriarch of the twelve tribes','A','Yaqub (Israil), son of Ishaq and father of Yusuf, was a prophet and patriarch; the Islamic reception of Jacob.'),
 ('ENT_ISL_YUSUF','Yusuf','Islamic','Prophet','Islamic prophet','interpreter of dreams; betrayal and rise in Egypt; chastity and forgiveness','A','Yusuf, son of Yaqub, was sold into Egypt and rose to power, subject of the Qur''an''s ''most beautiful story''; the Islamic reception of Joseph.'),
 ('ENT_ISL_AYYUB','Ayyub','Islamic','Prophet','Islamic prophet','patience (sabr) under affliction; restoration by God','A','Ayyub endured severe affliction with patience and was restored by God, an exemplar of sabr; the Islamic reception of Job.'),
 ('ENT_ISL_SHUAYB','Shu''ayb','Islamic','Messenger (rasul)','Islamic prophet','prophet to Madyan; honest weights and measures; monotheism','A','Shu''ayb was sent to the people of Madyan to enjoin honest dealing and monotheism; an Arabian prophet often linked, but not equated, with Jethro.'),
 ('ENT_ISL_MUSA','Musa','Islamic','Messenger (rasul)','Islamic prophet','kalim Allah (the one God spoke to); the Exodus; the Tawrah; Ulu al-Azm','A','Musa, the one to whom God spoke directly, led the Israelites from Egypt and received the Tawrah; the Islamic reception of Moses.'),
 ('ENT_ISL_HARUN','Harun','Islamic','Prophet','Islamic prophet','brother and helper (wazir) of Musa; spokesman before Pharaoh','A','Harun was the brother of Musa and his appointed helper and spokesman; the Islamic reception of Aaron.'),
 ('ENT_ISL_DHUL_KIFL','Dhul-Kifl','Islamic','Prophet','Islamic prophet','patience and steadfastness; often identified with Ezekiel','A','Dhul-Kifl is a patient prophet named among the righteous, commonly identified by Muslim tradition with Ezekiel.'),
 ('ENT_ISL_DAWUD','Dawud','Islamic','Prophet','Islamic prophet','prophet-king; slayer of Jalut (Goliath); the Zabur (Psalms); judgment and song','A','Dawud, the prophet-king who slew Jalut and received the Zabur, was given a beautiful voice and wisdom in judgment; the Islamic reception of David.'),
 ('ENT_ISL_SULAYMAN','Sulayman','Islamic','Prophet','Islamic prophet','prophet-king; command of wind, jinn, and animals; the Queen of Sheba','A','Sulayman, son of Dawud, was a prophet-king granted command over wind and jinn and knowledge of the speech of animals; the Islamic reception of Solomon.'),
 ('ENT_ISL_ILYAS','Ilyas','Islamic','Prophet','Islamic prophet','opposition to the worship of Baal; call to the one God','A','Ilyas called his people away from the worship of Baal to the one God; the Islamic reception of Elijah.'),
 ('ENT_ISL_AL_YASA','Al-Yasa','Islamic','Prophet','Islamic prophet','prophet among the righteous; successor in the line of Ilyas','A','Al-Yasa is named among the excellent prophets and follows in the line of Ilyas; the Islamic reception of Elisha.'),
 ('ENT_ISL_YUNUS','Yunus','Islamic','Messenger (rasul)','Islamic prophet','the prophet of the fish (Dhul-Nun); repentance; mission to Nineveh','A','Yunus, also called Dhul-Nun, was swallowed by a great fish and delivered after repenting, then sent to a people who believed; the Islamic reception of Jonah.'),
 ('ENT_ISL_ZAKARIYA','Zakariya','Islamic','Prophet','Islamic prophet','guardian of Maryam; granted a son (Yahya) in old age','A','Zakariya was guardian of Maryam and was granted the son Yahya in old age; counterpart of the New Testament Zechariah, father of John the Baptist.'),
 ('ENT_ISL_YAHYA','Yahya','Islamic','Prophet','Islamic prophet','son of Zakariya; wisdom in youth; righteousness and chastity','A','Yahya, son of Zakariya, was given wisdom as a child and was pure and devout; the Islamic reception of John the Baptist.'),
 ('ENT_ISL_ISA','Isa','Islamic','Messenger (rasul)','Islamic prophet','al-Masih (the Messiah); born of Maryam; the Injil; miracles by God''s leave; Ulu al-Azm','A','Isa al-Masih, son of Maryam, was born of a virgin, given the Injil, and worked miracles by God''s leave, regarded in Islam as prophet and not divine; the Islamic reception of Jesus.'),
 ('ENT_ISL_LUQMAN','Luqman','Islamic','Sage','Islamic sage','the sage granted wisdom (hikma); moral counsel to his son','A','Luqman is a wise man granted hikma by God who gives moral counsel to his son; revered as a sage (and by some a prophet), with no Biblical counterpart.');
INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
INSERT INTO _s VALUES
 ('ENT_ISR_PATRIARCHS','SRC_HEBREW_BIBLE','The three forefathers of Israel — Abraham, Isaac, and Jacob — invoked together as the recipients of the covenant.','primary text attestation'),
 ('ENT_ISR_MATRIARCHS','SRC_HEBREW_BIBLE','The four foremothers of Israel — Sarah, Rebecca, Rachel, and Leah — mothers of the covenant line.','primary text attestation'),
 ('ENT_ISR_TWELVE_TRIBES','SRC_HEBREW_BIBLE','The confederation of tribes descended from the sons of Jacob, who together constituted the people of Israel.','primary text attestation'),
 ('ENT_ISR_JUDGES','SRC_HEBREW_BIBLE','The charismatic deliverers who led the tribes of Israel in the period before the monarchy.','primary text attestation'),
 ('ENT_ISR_KINGS','SRC_HEBREW_BIBLE','The three successive kings of the united Israelite kingdom — Saul, David, and Solomon — before its division.','primary text attestation'),
 ('ENT_ISR_EVE','SRC_HEBREW_BIBLE','Formed as the first woman and ''mother of all living,'' she eats the forbidden fruit and bears Cain, Abel, and Seth.','primary text attestation'),
 ('ENT_ISR_CAIN','SRC_HEBREW_BIBLE','Firstborn son of Adam and Eve, a tiller of the ground who murdered his brother Abel and was marked and exiled.','primary text attestation'),
 ('ENT_ISR_ABEL','SRC_HEBREW_BIBLE','Second son of Adam and Eve, a keeper of sheep whose offering was favored and who was slain by his brother Cain.','primary text attestation'),
 ('ENT_ISR_SETH','SRC_HEBREW_BIBLE','Third son of Adam and Eve, given in place of slain Abel, through whose line Enosh, Enoch, and Noah descend.','primary text attestation'),
 ('ENT_ISR_ABRAHAM','SRC_HEBREW_BIBLE','First of the patriarchs, called from Ur, recipient of the covenant, father of Ishmael by Hagar and Isaac by Sarah.','primary text attestation'),
 ('ENT_ISR_SARAH','SRC_HEBREW_BIBLE','Wife of Abraham and first matriarch, who bore Isaac in old age after the promise of a son.','primary text attestation'),
 ('ENT_ISR_HAGAR','SRC_HEBREW_BIBLE','Egyptian servant of Sarah who bore Abraham''s son Ishmael and was met by the angel of Yahweh in the wilderness.','primary text attestation'),
 ('ENT_ISR_ISHMAEL','SRC_HEBREW_BIBLE','Firstborn son of Abraham by Hagar, ancestor of twelve princes, who dwelt in the wilderness of Paran.','primary text attestation'),
 ('ENT_ISR_LOT','SRC_HEBREW_BIBLE','Nephew of Abraham (son of Haran) who settled in Sodom and was delivered from its destruction (Genesis 13, 19).','primary text attestation'),
 ('ENT_ISR_ISAAC','SRC_HEBREW_BIBLE','Son of Abraham and Sarah, bound on Mount Moriah, husband of Rebecca, and father of Esau and Jacob.','primary text attestation'),
 ('ENT_ISR_REBECCA','SRC_HEBREW_BIBLE','Wife of Isaac, found at the well, mother of twins Esau and Jacob whom she helped secure the blessing.','primary text attestation'),
 ('ENT_ISR_JACOB','SRC_HEBREW_BIBLE','Son of Isaac and Rebecca, renamed Israel after wrestling at Peniel, father of the twelve sons who became the tribes of Israel.','primary text attestation'),
 ('ENT_ISR_RACHEL','SRC_HEBREW_BIBLE','Beloved wife of Jacob, mother of Joseph and Benjamin, who died in childbirth near Bethlehem.','primary text attestation'),
 ('ENT_ISR_LEAH','SRC_HEBREW_BIBLE','First wife of Jacob and mother of six of his sons, including Levi and Judah, ancestors of priesthood and kingship.','primary text attestation'),
 ('ENT_ISR_JOSEPH','SRC_HEBREW_BIBLE','Favored son of Jacob and Rachel, sold into Egypt, who rose to vizier and preserved his family during famine.','primary text attestation'),
 ('ENT_ISR_JUDAH','SRC_HEBREW_BIBLE','Fourth son of Jacob and Leah and ancestor of the royal Davidic line, blessed that the scepter would not depart.','primary text attestation'),
 ('ENT_ISR_LEVI','SRC_HEBREW_BIBLE','Third son of Jacob and Leah and ancestor of the priestly tribe of Levi, including Moses and Aaron.','primary text attestation'),
 ('ENT_ISR_BENJAMIN','SRC_HEBREW_BIBLE','Youngest son of Jacob and Rachel, born at her death, ancestor of the tribe of Benjamin and of King Saul.','primary text attestation'),
 ('ENT_ISR_AARON','SRC_HEBREW_BIBLE','Brother of Moses and Miriam, spokesman before Pharaoh, and the first high priest of Israel.','primary text attestation'),
 ('ENT_ISR_MIRIAM','SRC_HEBREW_BIBLE','Sister of Moses and Aaron, called a prophetess, who led the women in song after the crossing of the sea.','primary text attestation'),
 ('ENT_ISR_JOSHUA','SRC_HEBREW_BIBLE','Successor of Moses who led Israel across the Jordan and in the conquest of Canaan, dividing the land among the tribes.','primary text attestation'),
 ('ENT_ISR_CALEB','SRC_HEBREW_BIBLE','One of the twelve spies who, with Joshua, trusted in Yahweh and was rewarded with the inheritance of Hebron.','primary text attestation'),
 ('ENT_ISR_DEBORAH','SRC_HEBREW_BIBLE','Prophetess and judge who summoned Barak and celebrated the defeat of Sisera in the Song of Deborah.','primary text attestation'),
 ('ENT_ISR_GIDEON','SRC_HEBREW_BIBLE','Judge who, with three hundred men, delivered Israel from the Midianites after testing Yahweh with the fleece.','primary text attestation'),
 ('ENT_ISR_SAMSON','SRC_HEBREW_BIBLE','Nazirite judge of immense strength who fought the Philistines and died bringing down their temple at Gaza.','primary text attestation'),
 ('ENT_ISR_SAMUEL','SRC_HEBREW_BIBLE','Last judge and a prophet who anointed both Saul and David as kings of Israel.','primary text attestation'),
 ('ENT_ISR_SAUL','SRC_HEBREW_BIBLE','First king of Israel from the tribe of Benjamin, anointed by Samuel, rejected for disobedience, and slain at Gilboa.','primary text attestation'),
 ('ENT_ISR_DAVID','SRC_HEBREW_BIBLE','Shepherd anointed by Samuel who slew Goliath, became king over all Israel, and received the everlasting dynastic covenant.','primary text attestation'),
 ('ENT_ISR_BATHSHEBA','SRC_HEBREW_BIBLE','Wife of David, taken after the death of Uriah, and mother of King Solomon.','primary text attestation'),
 ('ENT_ISR_RUTH','SRC_HEBREW_BIBLE','Moabite widow whose loyalty to Naomi led to her marriage to Boaz, making her great-grandmother of King David.','primary text attestation'),
 ('ENT_ISR_ESTHER','SRC_HEBREW_BIBLE','Jewish queen of Persia who risked her life before Ahasuerus to save her people, commemorated at Purim.','primary text attestation'),
 ('ENT_ISR_MORDECAI','SRC_HEBREW_BIBLE','Kinsman and guardian of Esther who uncovered a plot, refused homage to Haman, and helped establish Purim.','primary text attestation'),
 ('ENT_ISR_JOB','SRC_HEBREW_BIBLE','A blameless man of Uz whose endurance of catastrophic suffering frames the book''s debate on divine justice.','primary text attestation'),
 ('ENT_ISR_EZRA','SRC_HEBREW_BIBLE','Priest and scribe who led returning exiles and re-established the Torah in restored Jerusalem.','primary text attestation'),
 ('ENT_ISR_NEHEMIAH','SRC_HEBREW_BIBLE','Cupbearer to the Persian king who became governor and rebuilt the walls of Jerusalem and reformed the community.','primary text attestation'),
 ('ENT_ISR_LATTER_PROPHETS','SRC_HEBREW_BIBLE','The prophetic canon division comprising the three Major Prophets and the Book of the Twelve, spanning the Assyrian, Babylonian, and Persian periods.','primary text attestation'),
 ('ENT_ISR_TWELVE_PROPHETS','SRC_HEBREW_BIBLE','A single scroll in the Hebrew canon gathering twelve shorter prophetic books from the 8th century BCE to the post-exilic restoration.','primary text attestation'),
 ('ENT_ISR_ISAIAH','SRC_HEBREW_BIBLE','An 8th-century BCE Judahite prophet whose oracles warn of judgment yet promise a remnant, a Davidic messiah, and a restored Zion.','primary text attestation'),
 ('ENT_ISR_JEREMIAH','SRC_HEBREW_BIBLE','A late 7th- to early 6th-century BCE prophet who foretold Jerusalem''s fall to Babylon and proclaimed a coming new covenant written on the heart.','primary text attestation'),
 ('ENT_ISR_EZEKIEL','SRC_HEBREW_BIBLE','A 6th-century BCE priest-prophet among the Babylonian exiles whose visions of the chariot, dry bones, and a restored temple promise renewal.','primary text attestation'),
 ('ENT_ISR_DANIEL_PROPHET','SRC_HEBREW_BIBLE','A Judahite exile at the Babylonian and Persian courts whose faithfulness and apocalyptic visions affirm God''s rule over the kingdoms of the world.','primary text attestation'),
 ('ENT_ISR_HOSEA','SRC_HEBREW_BIBLE','An 8th-century BCE prophet to the northern kingdom whose troubled marriage dramatizes Israel''s faithlessness and God''s enduring covenant love.','primary text attestation'),
 ('ENT_ISR_JOEL','SRC_HEBREW_BIBLE','A prophet of Judah who reads a devastating locust plague as a sign of the coming Day of the Lord and promises an outpouring of God''s Spirit.','primary text attestation'),
 ('ENT_ISR_AMOS','SRC_HEBREW_BIBLE','A mid-8th-century BCE Judahite shepherd who prophesied against the northern kingdom, condemning injustice and empty worship.','primary text attestation'),
 ('ENT_ISR_OBADIAH','SRC_HEBREW_BIBLE','Author of the shortest book of the Hebrew Bible, an oracle of judgment against Edom for its betrayal of Judah.','primary text attestation'),
 ('ENT_ISR_JONAH','SRC_HEBREW_BIBLE','A reluctant prophet, swallowed by a great fish, whose mission to Nineveh reveals God''s compassion even toward Israel''s enemies.','primary text attestation'),
 ('ENT_ISR_MICAH','SRC_HEBREW_BIBLE','An 8th-century BCE contemporary of Isaiah who called Israel to do justice, love mercy, and walk humbly with God.','primary text attestation'),
 ('ENT_ISR_NAHUM','SRC_HEBREW_BIBLE','A 7th-century BCE prophet who proclaimed the impending fall of Nineveh as God''s judgment on a cruel empire.','primary text attestation'),
 ('ENT_ISR_HABAKKUK','SRC_HEBREW_BIBLE','A late 7th-century BCE prophet who questioned God about the Babylonian threat and concluded that the righteous shall live by their faith.','primary text attestation'),
 ('ENT_ISR_ZEPHANIAH','SRC_HEBREW_BIBLE','A 7th-century BCE Judahite prophet during Josiah''s reign who warned of a sweeping Day of the Lord and promised salvation for a humble remnant.','primary text attestation'),
 ('ENT_ISR_HAGGAI','SRC_HEBREW_BIBLE','A post-exilic prophet of 520 BCE who urged the returned exiles to rebuild the Jerusalem temple and promised future glory.','primary text attestation'),
 ('ENT_ISR_ZECHARIAH','SRC_HEBREW_BIBLE','A post-exilic prophet, contemporary of Haggai, whose night visions encouraged the temple''s rebuilding and foretold a coming messianic king.','primary text attestation'),
 ('ENT_ISR_MALACHI','SRC_HEBREW_BIBLE','The last of the Twelve, a 5th-century BCE prophet who rebuked unfaithfulness and announced a coming messenger before the Day of the Lord.','primary text attestation'),
 ('ENT_ISR_ELISHA','SRC_HEBREW_BIBLE','A 9th-century BCE prophet of the northern kingdom who succeeded Elijah, receiving a double portion of his spirit and performing many miracles.','primary text attestation'),
 ('ENT_ISR_NATHAN','SRC_HEBREW_BIBLE','A 10th-century BCE court prophet under King David who delivered the Davidic covenant promise and rebuked David over Bathsheba and Uriah.','primary text attestation'),
 ('ENT_NT_TWELVE_APOSTLES','SRC_NEW_TESTAMENT','The twelve disciples chosen by Jesus as his closest followers and witnesses, the foundation of the apostolic Church.','primary text attestation'),
 ('ENT_NT_FOUR_EVANGELISTS','SRC_NEW_TESTAMENT','Matthew, Mark, Luke, and John — the traditional authors of the four canonical Gospels.','primary text attestation'),
 ('ENT_NT_PAULINE_CIRCLE','SRC_NEW_TESTAMENT','The missionary companions and coworkers of the apostle Paul named in Acts and the epistles — Barnabas, Mark, Luke, Timothy, and Titus.','primary text attestation'),
 ('ENT_NT_ANDREW','SRC_NEW_TESTAMENT','A fisherman of Bethsaida and brother of Simon Peter, called by Jesus to be a fisher of men and numbered among the Twelve.','primary text attestation'),
 ('ENT_NT_JOHN_APOSTLE','SRC_NEW_TESTAMENT','Son of Zebedee and brother of James the Greater, traditionally identified with the Beloved Disciple and reckoned both apostle and evangelist.','primary text attestation'),
 ('ENT_NT_PHILIP','SRC_NEW_TESTAMENT','A native of Bethsaida who, on being called by Jesus, sought out Nathanael with the words ''Come and see.''','primary text attestation'),
 ('ENT_NT_BARTHOLOMEW','SRC_NEW_TESTAMENT','Listed among the Twelve as Bartholomew and commonly identified with the Nathanael whom Jesus praised as guileless in John''s Gospel.','primary text attestation'),
 ('ENT_NT_THOMAS','SRC_NEW_TESTAMENT','An apostle called Didymus who doubted the resurrection until he saw the risen Christ, then confessed him as ''My Lord and my God.''','primary text attestation'),
 ('ENT_NT_MATTHEW','SRC_NEW_TESTAMENT','A tax collector (the Levi of Mark and Luke) called by Jesus, numbered among the Twelve and traditionally credited with the First Gospel.','primary text attestation'),
 ('ENT_NT_JAMES_ALPHAEUS','SRC_NEW_TESTAMENT','An apostle named in all four lists of the Twelve as the son of Alphaeus, distinct from James the son of Zebedee.','primary text attestation'),
 ('ENT_NT_JUDE_THADDAEUS','SRC_NEW_TESTAMENT','An apostle listed as Thaddaeus in Matthew and Mark and as Judas son (or brother) of James in Luke and Acts.','primary text attestation'),
 ('ENT_NT_SIMON_ZEALOT','SRC_NEW_TESTAMENT','An apostle of the Twelve called the Zealot (or Cananaean) to distinguish him from Simon Peter.','primary text attestation'),
 ('ENT_NT_JUDAS_ISCARIOT','SRC_NEW_TESTAMENT','The apostle who betrayed Jesus for thirty pieces of silver and afterward died, his place among the Twelve filled by Matthias.','primary text attestation'),
 ('ENT_NT_MATTHIAS','SRC_NEW_TESTAMENT','A disciple who had followed Jesus from his baptism and was chosen by lot to take the place of Judas Iscariot among the Twelve.','primary text attestation'),
 ('ENT_NT_MARK','SRC_NEW_TESTAMENT','John Mark, a companion of Paul, Barnabas, and Peter, traditionally identified as the author of the Second Gospel.','primary text attestation'),
 ('ENT_NT_LUKE','SRC_NEW_TESTAMENT','A physician and companion of Paul, traditionally credited with the Third Gospel and the Acts of the Apostles.','primary text attestation'),
 ('ENT_NT_BARNABAS','SRC_NEW_TESTAMENT','A Levite of Cyprus surnamed Barnabas (''son of encouragement'') who introduced Paul to the apostles and traveled with him as a missionary.','primary text attestation'),
 ('ENT_NT_TIMOTHY','SRC_NEW_TESTAMENT','A disciple of Lystra, son of a Jewish mother and Greek father, who became Paul''s close coworker and the recipient of two epistles.','primary text attestation'),
 ('ENT_NT_TITUS','SRC_NEW_TESTAMENT','A Greek coworker of Paul, sent to Corinth and left in Crete to set its churches in order, and the recipient of the Epistle to Titus.','primary text attestation'),
 ('ENT_NT_LAZARUS_BETHANY','SRC_NEW_TESTAMENT','The brother of Martha and Mary of Bethany, whom Jesus raised from the dead after four days in the tomb.','primary text attestation'),
 ('ENT_NT_MARTHA','SRC_NEW_TESTAMENT','A sister of Lazarus and Mary who served Jesus at Bethany and confessed him as the Christ, the Son of God.','primary text attestation'),
 ('ENT_NT_NICODEMUS','SRC_NEW_TESTAMENT','A Pharisee and member of the Sanhedrin who came to Jesus by night and later helped Joseph of Arimathea bury him.','primary text attestation'),
 ('ENT_ISL_PROPHETS','SRC_QURAN','The collective of prophets named in the Qur''an, from Adam to Muhammad, sent to guide humanity to the worship of the one God.','primary text attestation'),
 ('ENT_ISL_ULU_AL_AZM','SRC_QURAN','Ulu al-Azm (''those of firm resolve'') are the five greatest messengers in Islam: Nuh, Ibrahim, Musa, Isa, and Muhammad.','primary text attestation'),
 ('ENT_ISL_ADAM','SRC_QURAN','Adam, the first man and first prophet in Islam, created by God and taught the names of all things; the Islamic reception of the Biblical Adam.','primary text attestation'),
 ('ENT_ISL_NUH','SRC_QURAN','Nuh built the Ark at God''s command and was saved with the believers from the Flood; the Islamic reception of Noah.','primary text attestation'),
 ('ENT_ISL_HUD','SRC_QURAN','Hud was sent to the ancient Arabian people of ''Ad to call them from idolatry; an Arabian prophet with no Biblical counterpart.','primary text attestation'),
 ('ENT_ISL_SALIH','SRC_QURAN','Salih was sent to the Arabian people of Thamud with the sign of the she-camel; an Arabian prophet with no Biblical counterpart.','primary text attestation'),
 ('ENT_ISL_IBRAHIM','SRC_QURAN','Ibrahim, the friend of God, patriarch of monotheism who with his son built the Kaaba; the Islamic reception of Abraham.','primary text attestation'),
 ('ENT_ISL_LUT','SRC_QURAN','Lut warned his people against immorality before their destruction; the Islamic reception of Lot.','primary text attestation'),
 ('ENT_ISL_ISMAIL','SRC_QURAN','Ismail, son of Ibrahim, helped build the Kaaba and is regarded in Islam as the son offered in sacrifice; the Islamic reception of Ishmael.','primary text attestation'),
 ('ENT_ISL_ISHAQ','SRC_QURAN','Ishaq, son of Ibrahim, was given to him in old age and continued the prophetic line; the Islamic reception of Isaac.','primary text attestation'),
 ('ENT_ISL_YAQUB','SRC_QURAN','Yaqub (Israil), son of Ishaq and father of Yusuf, was a prophet and patriarch; the Islamic reception of Jacob.','primary text attestation'),
 ('ENT_ISL_YUSUF','SRC_QURAN','Yusuf, son of Yaqub, was sold into Egypt and rose to power, subject of the Qur''an''s ''most beautiful story''; the Islamic reception of Joseph.','primary text attestation'),
 ('ENT_ISL_AYYUB','SRC_QURAN','Ayyub endured severe affliction with patience and was restored by God, an exemplar of sabr; the Islamic reception of Job.','primary text attestation'),
 ('ENT_ISL_SHUAYB','SRC_QURAN','Shu''ayb was sent to the people of Madyan to enjoin honest dealing and monotheism; an Arabian prophet often linked, but not equated, with Jethro.','primary text attestation'),
 ('ENT_ISL_MUSA','SRC_QURAN','Musa, the one to whom God spoke directly, led the Israelites from Egypt and received the Tawrah; the Islamic reception of Moses.','primary text attestation'),
 ('ENT_ISL_HARUN','SRC_QURAN','Harun was the brother of Musa and his appointed helper and spokesman; the Islamic reception of Aaron.','primary text attestation'),
 ('ENT_ISL_DHUL_KIFL','SRC_QURAN','Dhul-Kifl is a patient prophet named among the righteous, commonly identified by Muslim tradition with Ezekiel.','primary text attestation'),
 ('ENT_ISL_DAWUD','SRC_QURAN','Dawud, the prophet-king who slew Jalut and received the Zabur, was given a beautiful voice and wisdom in judgment; the Islamic reception of David.','primary text attestation'),
 ('ENT_ISL_SULAYMAN','SRC_QURAN','Sulayman, son of Dawud, was a prophet-king granted command over wind and jinn and knowledge of the speech of animals; the Islamic reception of Solomon.','primary text attestation'),
 ('ENT_ISL_ILYAS','SRC_QURAN','Ilyas called his people away from the worship of Baal to the one God; the Islamic reception of Elijah.','primary text attestation'),
 ('ENT_ISL_AL_YASA','SRC_QURAN','Al-Yasa is named among the excellent prophets and follows in the line of Ilyas; the Islamic reception of Elisha.','primary text attestation'),
 ('ENT_ISL_YUNUS','SRC_QURAN','Yunus, also called Dhul-Nun, was swallowed by a great fish and delivered after repenting, then sent to a people who believed; the Islamic reception of Jonah.','primary text attestation'),
 ('ENT_ISL_ZAKARIYA','SRC_QURAN','Zakariya was guardian of Maryam and was granted the son Yahya in old age; counterpart of the New Testament Zechariah, father of John the Baptist.','primary text attestation'),
 ('ENT_ISL_YAHYA','SRC_QURAN','Yahya, son of Zakariya, was given wisdom as a child and was pure and devout; the Islamic reception of John the Baptist.','primary text attestation'),
 ('ENT_ISL_ISA','SRC_QURAN','Isa al-Masih, son of Maryam, was born of a virgin, given the Injil, and worked miracles by God''s leave, regarded in Islam as prophet and not divine; the Islamic reception of Jesus.','primary text attestation'),
 ('ENT_ISL_LUQMAN','SRC_QURAN','Luqman is a wise man granted hikma by God who gives moral counsel to his son; revered as a sage (and by some a prophet), with no Biblical counterpart.','primary text attestation');
